//==============================================================================
// tb_region_fill_hd.v -- ModelSim testbench for alg_region_fill_96 at the
//                        **real 1280x720** resolution (3 frames)
//
// Structurally identical to tb_region_fill.v (same contract assertions, same dump
// format).  Differences:
//   * 1280x720: 320 beats per line, 720 lines per frame, 3 frames = 691200 beats;
//   * no bubbles (bubbles are covered by the 32x10 round).
//
// Stimulus : stim_rf_hd.hex (generated by gen_stim_region_fill.py)
// Dump     : dump_rf_hd.txt
//              cyc Iv Il Iu Id Ov Ol Ou Od r_inside r_tlast r_tuser r_vld2
//
// Usage (from sim/):
//     vlog tb_region_fill_hd.v ../src/alg_region_fill_96.v
//     vsim -c -do "run -all; quit -f" tb_region_fill_hd
// English only in $display: ModelSim 10.3c transcript cannot show Chinese.
//==============================================================================
`timescale 1ns / 1ps

module tb_region_fill_hd;

    localparam IMG_WIDTH  = 1280;
    localparam IMG_HEIGHT = 720;
    localparam BPL        = IMG_WIDTH / 4;          // 320
    localparam FRAMES     = 3;
    localparam BPF        = BPL * IMG_HEIGHT;       // 230400 beats per frame
    localparam NBEAT      = BPF * FRAMES;           // 691200 beats
    localparam LAT        = 3;                      // module latency (RTL section 14)

    localparam RST_CYC    = 4;
    localparam START_CYC  = 6;

    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg [95:0] stim [0:NBEAT-1];

    reg [31:0] tb_cyc;
    reg [31:0] tb_beat;
    reg        rst_n;

    wire w_drv = (tb_cyc >= START_CYC) && (tb_beat < NBEAT);

    reg  [95:0] I_tdata;
    reg         I_tvalid;
    reg         I_tlast;
    reg         I_tuser;
    wire        I_tready;

    always @ (*) begin
        I_tdata  = w_drv ? stim[tb_beat] : 96'd0;
        I_tvalid = w_drv;
        I_tlast  = w_drv && (((tb_beat % BPL) == (BPL - 1)));
        I_tuser  = w_drv && (((tb_beat % BPF) == 0));
    end

    wire [95:0] O_tdata;
    wire        O_tvalid;
    wire        O_tlast;
    wire        O_tuser;
    wire        O_tready;

    alg_region_fill_96 #(
        .IMG_WIDTH  (IMG_WIDTH),
        .IMG_HEIGHT (IMG_HEIGHT)
    ) dut (
        .I_clk    (clk),
        .I_rst_n  (rst_n),
        .I_tdata  (I_tdata),
        .I_tvalid (I_tvalid),
        .I_tlast  (I_tlast),
        .I_tuser  (I_tuser),
        .I_tready (I_tready),
        .O_tdata  (O_tdata),
        .O_tvalid (O_tvalid),
        .O_tlast  (O_tlast),
        .O_tuser  (O_tuser),
        .O_tready (O_tready)
    );

    assign I_tready = 1'b1;

    wire w_probe_inside = dut.r_inside;     // read-only probe, see tb_region_fill.v
    wire w_probe_tlast  = dut.r_tlast;
    wire w_probe_tuser  = dut.r_tuser;
    wire w_probe_vld2   = dut.r_vld1;

    reg [LAT-1:0] vsr, lsr, usr;

    always @ (posedge clk) begin
        if (!rst_n) begin
            vsr <= {LAT{1'b0}};
            lsr <= {LAT{1'b0}};
            usr <= {LAT{1'b0}};
        end else begin
            vsr <= {vsr[LAT-2:0], I_tvalid};
            lsr <= {lsr[LAT-2:0], I_tvalid && I_tlast};
            usr <= {usr[LAT-2:0], I_tvalid && I_tuser};
        end
    end

    integer n_in_vld, n_out_vld;
    integer n_lat_err, n_last_err, n_user_err, n_valid_err, n_value_err;
    integer last_drv_cyc;

    initial begin
        n_in_vld = 0;  n_out_vld = 0;
        n_lat_err = 0; n_last_err = 0; n_user_err = 0;
        n_valid_err = 0; n_value_err = 0;
        last_drv_cyc = 0;
    end

    function automatic w_pix_legal;
        input [23:0] p;
        reg         a;
        reg         b;
        begin
            a = (p === 24'hFFFFFF);
            b = (p === 24'h000000);
            w_pix_legal = a | b;
        end
    endfunction

    integer fd;

    initial begin
        fd = $fopen("dump_rf_hd.txt", "w");
        if (fd == 0) begin
            $display("FATAL: cannot open dump_rf_hd.txt");
            $finish;
        end
        $readmemh("stim_rf_hd.hex", stim);
        $display("TB: loaded %0d beats, BPL=%0d BPF=%0d FRAMES=%0d", NBEAT, BPL, BPF, FRAMES);
    end

    initial begin
        tb_cyc  = 32'd0;
        tb_beat = 32'd0;
        rst_n   = 1'b0;
        #1;
        repeat (RST_CYC) @(posedge clk);
        rst_n = 1'b1;
        $display("TB: reset released at cycle %0d", tb_cyc);
    end

    always @(posedge clk) begin
        $fwrite(fd, "%0d %b %b %b %h %b %b %b %h %b %b %b %b\n",
                tb_cyc,
                I_tvalid, I_tlast, I_tuser, I_tdata,
                O_tvalid, O_tlast, O_tuser, O_tdata,
                w_probe_inside, w_probe_tlast, w_probe_tuser, w_probe_vld2);

        if (I_tvalid)  n_in_vld  = n_in_vld + 1;
        if (O_tvalid)  n_out_vld = n_out_vld + 1;
        if (w_drv)     last_drv_cyc = tb_cyc;

        tb_cyc <= tb_cyc + 32'd1;
        if (w_drv)
            tb_beat <= tb_beat + 32'd1;

        if ((tb_beat >= NBEAT) && (tb_cyc >= (last_drv_cyc + LAT + 20))) begin
            $fclose(fd);
            $display("ASSERT in_vld=%0d out_vld=%0d  (must be equal)", n_in_vld, n_out_vld);
            $display("ASSERT lat_err=%0d last_err=%0d user_err=%0d valid_err=%0d xz_or_illegal=%0d",
                     n_lat_err, n_last_err, n_user_err, n_valid_err, n_value_err);
            if ((n_in_vld != n_out_vld) || (n_lat_err != 0) || (n_last_err != 0) ||
                (n_user_err != 0) || (n_valid_err != 0) || (n_value_err != 0))
                $display("TB-RESULT: FAIL");
            else
                $display("TB-RESULT: PASS");
            $finish;
        end
    end

    always @(negedge clk) begin
        if (rst_n && (tb_cyc >= (START_CYC + LAT + 2))) begin
            if (O_tvalid !== vsr[LAT-1]) n_valid_err = n_valid_err + 1;
            if (O_tlast  !== lsr[LAT-1]) n_last_err  = n_last_err + 1;
            if (O_tuser  !== usr[LAT-1]) n_user_err  = n_user_err + 1;
            if (O_tvalid === 1'b1) begin
                if (!w_pix_legal(O_tdata[95:72])) n_value_err = n_value_err + 1;
                if (!w_pix_legal(O_tdata[71:48])) n_value_err = n_value_err + 1;
                if (!w_pix_legal(O_tdata[47:24])) n_value_err = n_value_err + 1;
                if (!w_pix_legal(O_tdata[23: 0])) n_value_err = n_value_err + 1;
            end
        end
    end

endmodule
